{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test",
    "check": "node --check server.js && node --check views.js && node --check task-priorities.js && node --check task-dates.js && node --check test/projects.test.js && node --check test/task-dates.test.js"
  }
}
import { createServer } from 'node:http';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import { projectListPage, projectPage } from './views.js';
import { TASK_PRIORITIES } from './task-priorities.js';
import { normalizeDueDate, normalizeDueRange, matchesDueRange } from './task-dates.js';

const databasePath = process.env.DB_PATH || 'data/workboard.sqlite';
mkdirSync(dirname(databasePath), { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec('PRAGMA foreign_keys = ON');
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL CHECK (length(trim(name)) > 0)
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id),
    title TEXT NOT NULL CHECK (length(trim(title)) > 0),
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
  );
  CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id)
`);
if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'priority')) {
  database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'default_task_priority')) {
  database.exec("ALTER TABLE projects ADD COLUMN default_task_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_task_priority IN ('Low', 'Normal', 'High'))");
}
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'due_date')) {
  database.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
}
const listProjects = database.prepare(`
  SELECT projects.id, projects.name, projects.archived,
    COUNT(tasks.id) AS total_count, COALESCE(SUM(tasks.completed), 0) AS completed_count
  FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id
  WHERE projects.archived = ?
  GROUP BY projects.id ORDER BY projects.id
`);
const findProject = database.prepare('SELECT id, name, archived, default_task_priority FROM projects WHERE id = ?');
const insertProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const setProjectArchived = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
const setDefaultTaskPriority = database.prepare('UPDATE projects SET default_task_priority = ? WHERE id = ?');
const listTasks = database.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? ORDER BY id');
const insertTask = database.prepare('INSERT INTO tasks (project_id, title, priority) VALUES (?, ?, ?)');
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
const findTask = database.prepare('SELECT id FROM tasks WHERE id = ? AND project_id = ?');
const renameTask = database.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?');
const setTaskPriority = database.prepare('UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ?');
const setTaskDueDate = database.prepare('UPDATE tasks SET due_date = ? WHERE id = ? AND project_id = ?');

function taskFilter(value) {
  return ['Open', 'Completed'].includes(value) ? value : 'All';
}

function priorityFilter(value) {
  return TASK_PRIORITIES.includes(value) ? value : 'All';
}

function appliedDueRange(parameters) {
  const range = normalizeDueRange(parameters.get('dueFrom') || '', parameters.get('dueThrough') || '');
  return range.error ? { from: '', through: '' } : range;
}

function projectLocation(id, filter, priority, range) {
  const query = new URLSearchParams({ filter });
  if (priority !== 'All') query.set('priorityFilter', priority);
  if (range.from) query.set('dueFrom', range.from);
  if (range.through) query.set('dueThrough', range.through);
  return `/projects/${id}?${query}`;
}

function projectFilter(value) {
  return value === 'Archived' ? 'Archived' : 'Active';
}

function renderProjects(filter, error = '') {
  return projectListPage(listProjects.all(filter === 'Archived' ? 1 : 0), error, filter);
}

function renderProject(project, filter, priority, errors = {}, range = { from: '', through: '' }) {
  const tasks = listTasks.all(project.id).filter((task) => (
    (filter === 'All' || Boolean(task.completed) === (filter === 'Completed'))
    && (priority === 'All' || task.priority === priority)
    && matchesDueRange(task.due_date, range)
  ));
  return projectPage(project, tasks, filter, priority, errors, range);
}

function redirect(response, location) {
  response.writeHead(303, { Location: location });
  response.end();
}

function send(response, status, content, contentType = 'text/html; charset=utf-8') {
  response.writeHead(status, { 'Content-Type': contentType });
  response.end(content);
}

async function readForm(request) {
  const chunks = [];
  let length = 0;
  for await (const chunk of request) {
    length += chunk.length;
    if (length > 16384) {
      const error = new Error('Request body is too large');
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

const server = createServer(async (request, response) => {
  try {
    const { pathname, searchParams } = new URL(request.url, 'http://localhost');
    const projectRoute = pathname.match(/^\/projects\/(?<projectId>[1-9]\d*)(?:\/tasks(?:\/(?<taskId>[1-9]\d*)(?:\/(?<taskAction>rename|priority|due-date))?)?|\/(?<projectAction>archive|restore|rename|default-priority|due-range))?$/);
    if (request.method === 'GET' && pathname === '/health') {
      send(response, 200, JSON.stringify({ status: 'ok' }), 'application/json');
    } else if (request.method === 'GET' && pathname === '/') {
      send(response, 200, renderProjects(projectFilter(searchParams.get('filter'))));
    } else if (request.method === 'POST' && pathname === '/projects') {
      const form = await readForm(request);
      const name = (form.get('name') || '').trim();
      const filter = projectFilter(form.get('filter'));
      if (!name) {
        send(response, 400, renderProjects(filter, 'Project name is required'));
        return;
      }
      insertProject.run(name);
      redirect(response, '/');
    } else if (projectRoute) {
      const { projectId, taskId: taskIdValue, taskAction, projectAction } = projectRoute.groups;
      const id = Number(projectId);
      const project = Number.isSafeInteger(id) ? findProject.get(id) : undefined;
      if (!project) {
        send(response, 404, 'Project not found', 'text/plain; charset=utf-8');
        return;
      }
      if (request.method === 'GET' && pathname === `/projects/${id}`) {
        send(response, 200, renderProject(project, taskFilter(searchParams.get('filter')), priorityFilter(searchParams.get('priorityFilter')), {}, appliedDueRange(searchParams)));
      } else if (request.method === 'POST' && projectAction === 'due-range') {
        const form = await readForm(request);
        const filter = taskFilter(form.get('filter'));
        const priority = priorityFilter(form.get('priorityFilter'));
        const range = normalizeDueRange(form.get('rangeFrom') || '', form.get('rangeThrough') || '');
        if (range.error) {
          send(response, 400, renderProject(project, filter, priority, {
            dueRange: range.error,
            rangeFrom: form.get('rangeFrom') || '',
            rangeThrough: form.get('rangeThrough') || '',
          }, appliedDueRange(form)));
          return;
        }
        redirect(response, projectLocation(id, filter, priority, range));
      } else if (request.method === 'POST' && projectAction === 'rename') {
        if (project.archived) {
          send(response, 403, 'Archived project', 'text/plain; charset=utf-8');
          return;
        }
        const form = await readForm(request);
        const name = (form.get('name') || '').trim();
        const filter = taskFilter(form.get('filter'));
        const priority = priorityFilter(form.get('priorityFilter'));
        const appliedRange = appliedDueRange(form);
        if (!name) {
          send(response, 400, renderProject(project, filter, priority, { projectRename: 'Project name is required' }, appliedRange));
          return;
        }
        renameProject.run(name, id);
        redirect(response, projectLocation(id, filter, priority, appliedRange));
      } else if (request.method === 'POST' && projectAction === 'default-priority') {
        if (project.archived) {
          send(response, 403, 'Archived project', 'text/plain; charset=utf-8');
          return;
        }
        const form = await readForm(request);
        const newPriority = form.get('priority');
        if (!TASK_PRIORITIES.includes(newPriority)) {
          send(response, 400, 'Invalid task priority', 'text/plain; charset=utf-8');
          return;
        }
        setDefaultTaskPriority.run(newPriority, id);
        redirect(response, projectLocation(id, taskFilter(form.get('filter')), priorityFilter(form.get('priorityFilter')), appliedDueRange(form)));
      } else if (request.method === 'POST' && projectAction) {
        const archive = projectAction === 'archive';
        setProjectArchived.run(archive ? 1 : 0, id);
        redirect(response, archive ? '/' : '/?filter=Archived');
      } else if (request.method === 'POST' && pathname.includes('/tasks')) {
        if (project.archived) {
          send(response, 403, 'Archived project', 'text/plain; charset=utf-8');
          return;
        }
        const form = await readForm(request);
        const filter = taskFilter(form.get('filter'));
        const priority = priorityFilter(form.get('priorityFilter'));
        const appliedRange = appliedDueRange(form);
        if (taskIdValue) {
          const taskId = Number(taskIdValue);
          if (!Number.isSafeInteger(taskId) || !findTask.get(taskId, id)) {
            send(response, 404, 'Task not found', 'text/plain; charset=utf-8');
            return;
          }
          if (taskAction === 'rename') {
            const title = (form.get('title') || '').trim();
            if (!title) {
              send(response, 400, renderProject(project, filter, priority, {
                taskRename: { id: taskId, message: 'Task title is required' },
              }, appliedRange));
              return;
            }
            renameTask.run(title, taskId, id);
          } else if (taskAction === 'due-date') {
            const dueDate = normalizeDueDate(form.get('dueDate') || '');
            if (dueDate === null) {
              send(response, 400, renderProject(project, filter, priority, {
                taskDueDate: { id: taskId, message: 'Due date must be a valid YYYY-MM-DD date' },
              }, appliedRange));
              return;
            }
            setTaskDueDate.run(dueDate, taskId, id);
          } else if (taskAction === 'priority') {
            const newPriority = form.get('priority');
            if (!TASK_PRIORITIES.includes(newPriority)) {
              send(response, 400, 'Invalid task priority', 'text/plain; charset=utf-8');
              return;
            }
            setTaskPriority.run(newPriority, taskId, id);
          } else {
            updateTask.run(form.get('completed') === '1' ? 1 : 0, taskId, id);
          }
        } else {
          const title = (form.get('title') || '').trim();
          if (!title) {
            send(response, 400, renderProject(project, filter, priority, { taskCreation: 'Task title is required' }, appliedRange));
            return;
          }
          insertTask.run(id, title, project.default_task_priority);
        }
        redirect(response, projectLocation(id, filter, priority, appliedRange));
      } else {
        send(response, 404, 'Not found', 'text/plain; charset=utf-8');
      }
    } else {
      send(response, 404, 'Not found', 'text/plain; charset=utf-8');
    }
  } catch (error) {
    console.error(error);
    if (!response.headersSent) {
      send(response, error.status || 500, error.status ? error.message : 'Internal server error', 'text/plain; charset=utf-8');
    } else response.end();
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.once(signal, () => {
    server.close(() => {
      database.close();
    });
  });
}
import { TASK_PRIORITIES } from './task-priorities.js';

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function page(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)} · Workboard</title>
  <style>
    * { box-sizing: border-box; }
    body { margin: 0; background: #f5f7fa; color: #172334; font-family: system-ui, sans-serif; }
    main { max-width: 760px; margin: 64px auto; padding: 0 24px; }
    h1 { overflow-wrap: anywhere; font-size: 36px; margin: 0 0 32px; }
    .create-form { background: white; padding: 24px; border: 1px solid #d7dfe8; border-radius: 12px; }
    label { display: block; font-weight: 600; margin-bottom: 8px; }
    .form-controls { display: flex; gap: 12px; }
    input { min-width: 0; flex: 1; border: 1px solid #8996a8; border-radius: 6px; padding: 10px 12px; font: inherit; }
    button { border: 1px solid #285ad1; border-radius: 6px; background: #285ad1; color: white; padding: 10px 16px; font: inherit; font-weight: 600; cursor: pointer; }
    button:hover { background: #204bad; }
    button:disabled { background: #738096; border-color: #738096; cursor: default; }
    :focus-visible { outline: 3px solid #ad6c00; outline-offset: 3px; }
    [role="alert"] { color: #a21b25; margin: 0 0 16px; }
    .projects { margin-top: 24px; display: grid; gap: 12px; }
    .project-row { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 16px; background: white; border: 1px solid #d7dfe8; border-radius: 10px; padding: 18px 24px; }
    .project-name { overflow-wrap: anywhere; min-width: 0; font-weight: 600; }
    .project-row form { flex-shrink: 0; }
    .task-create { margin-top: 24px; }
    .task-filter { margin-top: 24px; }
    select { padding: 10px 12px; font: inherit; border: 1px solid #8996a8; border-radius: 6px; background: white; }
    .task-row { background: white; border: 1px solid #d7dfe8; border-radius: 10px; padding: 18px 24px; }
    .task-row label { display: flex; align-items: center; gap: 12px; margin: 0; overflow-wrap: anywhere; }
    .task-row input[type="checkbox"] { flex: none; width: 20px; height: 20px; }
    .task-rename { margin-top: 16px; }
    .task-rename label { display: block; margin-bottom: 8px; }
    .task-rename input { width: 100%; margin-bottom: 12px; }
    @media (max-width: 520px) { main { margin-top: 32px; } .form-controls { flex-direction: column; } .project-row { padding: 16px; } }
  </style>
</head>
<body><main>${content}</main></body>
</html>`;
}

export function projectListPage(projects, error = '', filter = 'Active') {
  return page('Projects', `
    <h1>Workboard</h1>
    <form class="create-form" method="post" action="/projects">
      ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
      <input type="hidden" name="filter" value="${filter}">
      <label for="project-name">Project name</label>
      <div class="form-controls">
        <input id="project-name" name="name" type="text">
        <button type="submit">Create project</button>
      </div>
    </form>
    <form class="task-filter" method="get" action="/">
      <label for="project-filter">Project filter</label>
      <select id="project-filter" name="filter" onchange="this.form.requestSubmit()">
        ${['Active', 'Archived'].map((option) => `<option${filter === option ? ' selected' : ''}>${option}</option>`).join('')}
      </select>
    </form>
    <div class="projects">
      ${projects.map((project) => `<div class="project-row" data-testid="project-row">
        <span class="project-name">${escapeHtml(project.name)}</span>
        <span data-testid="project-summary">${project.completed_count}/${project.total_count} completed</span>
        <form method="get" action="/projects/${project.id}"><button type="submit">Open project</button></form>
        <form method="post" action="/projects/${project.id}/${project.archived ? 'restore' : 'archive'}"><button type="submit">${project.archived ? 'Restore' : 'Archive'} project</button></form>
      </div>`).join('')}
    </div>`);
}

export function projectPage(project, tasks = [], filter = 'All', priorityFilter = 'All', errors = {}, range = { from: '', through: '' }) {
  const rangeInputs = `<input type="hidden" name="dueFrom" value="${escapeHtml(range.from)}">
    <input type="hidden" name="dueThrough" value="${escapeHtml(range.through)}">`;
  return page(project.name, `<h1>${escapeHtml(project.name)}</h1>
    ${project.archived ? '<p>Archived project</p>' : ''}
    <form method="get" action="/"><button type="submit">Projects</button></form>
    <form class="create-form task-create" method="post" action="/projects/${project.id}/rename">
      ${errors.projectRename ? `<p role="alert">${escapeHtml(errors.projectRename)}</p>` : ''}
      <input type="hidden" name="filter" value="${filter}">
      <input type="hidden" name="priorityFilter" value="${priorityFilter}">
      ${rangeInputs}
      <label for="new-project-name">New project name</label>
      <div class="form-controls">
        <input id="new-project-name" name="name" type="text" value="${escapeHtml(project.name)}"${project.archived ? ' disabled' : ''}>
        <button type="submit"${project.archived ? ' disabled' : ''}>Rename project</button>
      </div>
    </form>
    <form class="task-filter" method="post" action="/projects/${project.id}/default-priority">
      <input type="hidden" name="filter" value="${filter}">
      <input type="hidden" name="priorityFilter" value="${priorityFilter}">
      ${rangeInputs}
      <label for="default-task-priority">Default task priority</label>
      <select id="default-task-priority" name="priority"${project.archived ? ' disabled' : ''} onchange="this.form.requestSubmit()">
        ${TASK_PRIORITIES.map((priority) => `<option${project.default_task_priority === priority ? ' selected' : ''}>${priority}</option>`).join('')}
      </select>
    </form>
    <form class="create-form task-create" method="post" action="/projects/${project.id}/tasks">
      ${errors.taskCreation ? `<p role="alert">${escapeHtml(errors.taskCreation)}</p>` : ''}
      <input type="hidden" name="filter" value="${filter}">
      <input type="hidden" name="priorityFilter" value="${priorityFilter}">
      ${rangeInputs}
      <label for="task-title">Task title</label>
      <div class="form-controls">
        <input id="task-title" name="title" type="text">
        <button type="submit"${project.archived ? ' disabled' : ''}>Create task</button>
      </div>
    </form>
    <form class="task-filter" method="get" action="/projects/${project.id}">
      ${rangeInputs}
      <label for="task-filter">Task filter</label>
      <select id="task-filter" name="filter" onchange="this.form.requestSubmit()">
        ${['All', 'Open', 'Completed'].map((option) => `<option${filter === option ? ' selected' : ''}>${option}</option>`).join('')}
      </select>
      <label for="priority-filter">Priority filter</label>
      <select id="priority-filter" name="priorityFilter" onchange="this.form.requestSubmit()">
        ${['All', ...TASK_PRIORITIES].map((option) => `<option${priorityFilter === option ? ' selected' : ''}>${option}</option>`).join('')}
      </select>
    </form>
    <form class="task-filter" method="post" action="/projects/${project.id}/due-range">
      ${errors.dueRange ? `<p role="alert">${escapeHtml(errors.dueRange)}</p>` : ''}
      <input type="hidden" name="filter" value="${filter}">
      <input type="hidden" name="priorityFilter" value="${priorityFilter}">
      ${rangeInputs}
      <label for="due-from">Due from</label>
      <input id="due-from" name="rangeFrom" type="text" value="${escapeHtml(errors.rangeFrom ?? range.from)}">
      <label for="due-through">Due through</label>
      <input id="due-through" name="rangeThrough" type="text" value="${escapeHtml(errors.rangeThrough ?? range.through)}">
      <button type="submit">Apply due range</button>
    </form>
    <div class="projects">
      ${tasks.map((task) => `<div class="task-row" data-testid="task-row">
        <form method="post" action="/projects/${project.id}/tasks/${task.id}">
          <input type="hidden" name="filter" value="${filter}">
          <input type="hidden" name="priorityFilter" value="${priorityFilter}">
          ${rangeInputs}
          <label><input type="checkbox" name="completed" value="1" aria-label="Complete ${escapeHtml(task.title)}"${task.completed ? ' checked' : ''}${project.archived ? ' disabled' : ''} onchange="this.form.requestSubmit()"><span>${escapeHtml(task.title)}</span></label>
        </form>
        <form class="task-filter" method="post" action="/projects/${project.id}/tasks/${task.id}/priority">
          <input type="hidden" name="filter" value="${filter}">
          <input type="hidden" name="priorityFilter" value="${priorityFilter}">
          ${rangeInputs}
          <label for="task-priority-${task.id}">Task priority</label>
          <select id="task-priority-${task.id}" name="priority"${project.archived ? ' disabled' : ''} onchange="this.form.requestSubmit()">
            ${TASK_PRIORITIES.map((priority) => `<option${task.priority === priority ? ' selected' : ''}>${priority}</option>`).join('')}
          </select>
        </form>
        <form class="task-rename" method="post" action="/projects/${project.id}/tasks/${task.id}/rename">
          ${errors.taskRename?.id === task.id ? `<p role="alert">${escapeHtml(errors.taskRename.message)}</p>` : ''}
          <input type="hidden" name="filter" value="${filter}">
          <input type="hidden" name="priorityFilter" value="${priorityFilter}">
          ${rangeInputs}
          <label for="new-task-title-${task.id}">New task title</label>
          <input id="new-task-title-${task.id}" name="title" type="text" value="${escapeHtml(task.title)}"${project.archived ? ' disabled' : ''}>
          <button type="submit"${project.archived ? ' disabled' : ''}>Rename task</button>
        </form>
        <form class="task-rename" method="post" action="/projects/${project.id}/tasks/${task.id}/due-date">
          ${errors.taskDueDate?.id === task.id ? `<p role="alert">${escapeHtml(errors.taskDueDate.message)}</p>` : ''}
          <input type="hidden" name="filter" value="${filter}">
          <input type="hidden" name="priorityFilter" value="${priorityFilter}">
          ${rangeInputs}
          <label for="task-due-date-${task.id}">Task due date</label>
          <input id="task-due-date-${task.id}" name="dueDate" type="text" value="${escapeHtml(task.due_date)}"${project.archived ? ' disabled' : ''}>
          <button type="submit"${project.archived ? ' disabled' : ''}>Save due date</button>
        </form>
      </div>`).join('')}
    </div>`);
}

# Workboard

Requires Node.js 22.22.1. No external dependencies or installation step are needed.

```sh
npm start
```

The server binds to `0.0.0.0` using `PORT` (default `8080`). SQLite data is stored
at `DB_PATH` (default `data/workboard.sqlite`); keep this file to preserve projects and tasks
across restarts. Parent directories are created automatically.

```sh
PORT=8080 DB_PATH=data/workboard.sqlite npm start
npm test
npm run check
```

`GET /health` returns HTTP 200 with `{"status":"ok"}`. The application uses
server-rendered HTML and standard browser forms. Project names are trimmed on
creation and escaped for display; project IDs provide stable URLs.
Each project owns its tasks. Task titles are trimmed and escaped for display.
Completion changes are saved immediately; the All, Open, and Completed filters
retain creation order. The selected filter is stored in the project page URL.

The project list initially shows Active projects; choose Archived to open or
restore archived projects. Archiving preserves tasks and completion state but
disables task creation and completion changes, including direct POST requests.
Each project summary counts all its tasks regardless of task filters. Existing
SQLite databases are migrated automatically, with existing projects initially
active. Archive state and task data persist across restarts.

Active projects can be renamed from their project page. Names are trimmed and
must not be blank. Renaming preserves the project ID, URL, creation order, tasks,
and completion summary. Archived projects cannot be renamed until restored;
this restriction also applies to direct POST requests. Renamed names persist
across restarts.

Each task in an active project can be renamed using its New task title field.
Titles are trimmed and must not be blank. Renaming preserves ownership,
creation order, completion state, filter membership, and completion summaries.
The displayed title and completion checkbox label update together. Archived
projects disable task renaming and reject direct rename requests until restored.
Renamed titles persist across restarts.

